{
  "implementation": "import math
def solve(case):
    matrix = case["matrix"]
    N = len(matrix)
    if N == 0:
        return {"idf": [], "row_degree": [], "weighted_matrix": []}
    cols = len(matrix[0])
    df = [0] * cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    idf = [0.0] * cols
    for j in range(cols):
        if df[j] == 0:
            idf[j] = 0.0
        else:
            idf[j] = math.log(N / df[j])
    row_degree = [sum(row) for row in matrix]
    weighted = []
    for row in matrix:
        weighted_row = [idf[j] if row[j] != 0 else 0.0 for j in range(cols)]
        weighted.append(weighted_row)
    return {"idf": idf, "row_degree": row_degree, "weighted_matrix": weighted}"
}
